record.field:
contribution_type = version.l10n_hk_member_class_ct_ervc_id

if contribution_type.definition_of_income == 'basic_salary':
    mpf_relevant_income = l10n_hk_payrun_category_totals['HK_BASIC'] + categories['HK_BASIC']
else:
    mpf_relevant_income = l10n_hk_payrun_totals['GROSS'] + result_rules['GROSS']['total']

is_exempt = version.l10n_hk_mpf_exempt
if contribution_type.contribution_option == 'percentage':
    contribution_amount = ((contribution_type.amount / 100) * mpf_relevant_income)
    result = -(abs(contribution_amount) - abs(l10n_hk_payrun_totals['ERVC']))
elif contribution_type.contribution_option == 'fixed':
    result = -payslip._l10n_hk_hr_payroll_from_to_schedule(contribution_type.amount * worked_days_prorata_rate, from_schedule='monthly')
elif contribution_type.contribution_option == 'match':
    result = result_rules['EEVC']['total']
else:  # Top up
    contribution_amount = max(((contribution_type.amount / 100) * mpf_relevant_income) - (0 if is_exempt else (0.05 * l10n_hk_mpf_maximum_relevant_income)), 0)
    result = -(abs(contribution_amount) - abs(l10n_hk_payrun_totals['ERVC']))

